// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(amount > 0 && amount < type(uint256).max);
        vm.assume(actor != address(0) && actor != address(c));
        vm.deal(actor, amount);
        uint256 beforeBalance = c.getBalance(actor);
        vm.prank(actor);
        c.addToBalance{value: amount}();
        uint256 afterBalance = c.getBalance(actor);
        assertTrue(afterBalance > beforeBalance);
    }
}
